import{_ as t,o as e,c as o,a0 as c}from"./chunks/framework.DqMqoJl9.js";const E=JSON.parse('{"title":"API Системы паспортного учёта (ППО «Территория»)","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),r={name:"api/index.md"};function a(i,d,l,h,n,s){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="api-системы-паспортного-учета-ппо-«территория»" tabindex="-1">API Системы паспортного учёта (ППО «Территория») <a class="header-anchor" href="#api-системы-паспортного-учета-ппо-«территория»" aria-label="Permalink to &quot;API Системы паспортного учёта (ППО «Территория»)&quot;">​</a></h1><h2 id="общие-сведения" tabindex="-1">Общие сведения <a class="header-anchor" href="#общие-сведения" aria-label="Permalink to &quot;Общие сведения&quot;">​</a></h2><ul><li><strong>Тип взаимодействия</strong>: Внутренний API между модулями ПО СС / ПО МС и БД (Oracle).</li><li><strong>Формат данных</strong>: JSON (при обмене между сервисами), прямые SQL-вызовы к БД.</li><li><strong>Версия</strong>: 1.0</li></ul><h2 id="основные-эндпоинты-операции" tabindex="-1">Основные эндпоинты / Операции <a class="header-anchor" href="#основные-эндпоинты-операции" aria-label="Permalink to &quot;Основные эндпоинты / Операции&quot;">​</a></h2><h3 id="_1-управление-лицами-и-документами" tabindex="-1">1. Управление лицами и документами <a class="header-anchor" href="#_1-управление-лицами-и-документами" aria-label="Permalink to &quot;1. Управление лицами и документами&quot;">​</a></h3><ul><li><code>POST /api/person/create</code> (вызов <code>PersonProvider.Save</code>) — Создание/обновление физического лица.</li><li><code>POST /api/document/issue</code> (вызов <code>DocumentProvider.Issue</code>) — Выдача документа (Сценарий №1).</li><li><code>POST /api/case/create</code> (вызов <code>CaseProvider.Create</code>) — Оформление дела.</li></ul><h3 id="_2-справочники" tabindex="-1">2. Справочники <a class="header-anchor" href="#_2-справочники" aria-label="Permalink to &quot;2. Справочники&quot;">​</a></h3><ul><li><code>GET /api/dict/country</code> — Получение справочника стран (локальный CSV / таблица <code>DICT_COUNTRY</code>).</li><li><code>GET /api/dict/document-types</code> — Типы документов (<code>DICT_DOCUMENT_TYPE</code>).</li></ul><h3 id="_3-миграция-и-учет-отчетность" tabindex="-1">3. Миграция и учет (отчетность) <a class="header-anchor" href="#_3-миграция-и-учет-отчетность" aria-label="Permalink to &quot;3. Миграция и учет (отчетность)&quot;">​</a></h3><ul><li><code>POST /api/mig/labour-report</code> — Формирование формы ИР (данные из <code>MIG_LABOURMIGDATA</code>).</li><li><code>POST /api/mig/unreg</code> — Снятие с учета (данные из <code>MIG_UNREG_DATA</code>).</li></ul><h2 id="сверка-полеи-операции-с-таблицами-бд" tabindex="-1">Сверка полей операций с таблицами БД <a class="header-anchor" href="#сверка-полеи-операции-с-таблицами-бд" aria-label="Permalink to &quot;Сверка полей операций с таблицами БД&quot;">​</a></h2><h3 id="операция-issuenewdocument-выдача-документа" tabindex="-1">Операция: <code>issueNewDocument</code> (Выдача документа) <a class="header-anchor" href="#операция-issuenewdocument-выдача-документа" aria-label="Permalink to &quot;Операция: `issueNewDocument` (Выдача документа)&quot;">​</a></h3><p>Соответствие полей JSON-запроса и таблиц БД:</p><table tabindex="0"><thead><tr><th>Поле в API (JSON)</th><th>Таблица БД</th><th>Поле в БД</th><th>Тип в БД</th><th>Обяз.</th><th>Примечание</th></tr></thead><tbody><tr><td><code>personId</code></td><td><code>CORE_PERSON</code></td><td><code>ID</code></td><td>NUMBER</td><td>✓</td><td>Идентификатор лица</td></tr><tr><td><code>firstName</code></td><td><code>CORE_PERSONDATA</code></td><td><code>FIRSTNAME</code></td><td>VARCHAR2(100)</td><td>✓</td><td>Имя</td></tr><tr><td><code>lastName</code></td><td><code>CORE_PERSONDATA</code></td><td><code>LASTNAME</code></td><td>VARCHAR2(200)</td><td>✓</td><td>Фамилия</td></tr><tr><td><code>middleName</code></td><td><code>CORE_PERSONDATA</code></td><td><code>MIDDLENAME</code></td><td>VARCHAR2(100)</td><td></td><td>Отчество</td></tr><tr><td><code>birthDate</code></td><td><code>CORE_PERSONDATA</code></td><td><code>BIRTHDATE</code></td><td>DATE</td><td></td><td>Дата рождения</td></tr><tr><td><code>documentType</code></td><td><code>CORE_DOCUMENT</code></td><td><code>DOCUMENTTYPE_ID</code></td><td>NUMBER</td><td>✓</td><td>FK на <code>DICT_DOCUMENT_TYPE</code></td></tr><tr><td><code>docSeries</code></td><td><code>CORE_DOCUMENT</code></td><td><code>DOCUMENTSERIES</code></td><td>VARCHAR2(30)</td><td></td><td>Серия</td></tr><tr><td><code>docNumber</code></td><td><code>CORE_DOCUMENT</code></td><td><code>DOCUMENTNUMBER</code></td><td>VARCHAR2(50)</td><td>✓</td><td>Номер</td></tr><tr><td><code>issueDate</code></td><td><code>CORE_DOCUMENT</code></td><td><code>DOCUMENTISSUEDDATE</code></td><td>DATE</td><td>✓</td><td>Дата выдачи</td></tr><tr><td><code>caseId</code></td><td><code>CORE_CASE</code></td><td><code>ID</code></td><td>NUMBER</td><td>✓</td><td>Привязка к делу</td></tr></tbody></table><h3 id="операция-createlabourmigreport-форма-ир-миграция" tabindex="-1">Операция: <code>createLabourMigReport</code> (Форма ИР / Миграция) <a class="header-anchor" href="#операция-createlabourmigreport-форма-ир-миграция" aria-label="Permalink to &quot;Операция: `createLabourMigReport` (Форма ИР / Миграция)&quot;">​</a></h3><p>Соответствие полей для отчета по трудовой миграции:</p><table tabindex="0"><thead><tr><th>Поле в API (JSON)</th><th>Таблица БД</th><th>Поле в БД</th><th>Тип в БД</th><th>Обяз.</th><th>Примечание</th></tr></thead><tbody><tr><td><code>personId</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>ID</code> (связь)</td><td>NUMBER</td><td>✓</td><td>Временное хранение</td></tr><tr><td><code>isPermitted</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>ISPERMITTED</code></td><td>NUMBER(1)</td><td>✓</td><td>Патент/разрешение</td></tr><tr><td><code>issuedWorkPerm</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>ISSUEDWORKPERMISSION</code></td><td>NUMBER(1)</td><td>✓</td><td>Выдано разрешение</td></tr><tr><td><code>permitSeries</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>PERMITSERIES</code></td><td>VARCHAR2(30)</td><td></td><td>Серия разрешения</td></tr><tr><td><code>permitNumber</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>PERMITNUMBER</code></td><td>VARCHAR2(50)</td><td></td><td>Номер разрешения</td></tr><tr><td><code>permitValidTo</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>PERMITVALIDTO</code></td><td>DATE</td><td></td><td>Срок действия</td></tr><tr><td><code>citizenshipCode</code></td><td><code>MIG_LABOURMIGDATA</code></td><td><code>CITIZENSHIPALPHACODE</code></td><td>VARCHAR2(30)</td><td></td><td>Код гражданства</td></tr></tbody></table><h3 id="операция-unregisterperson-снятие-с-учета" tabindex="-1">Операция: <code>unregisterPerson</code> (Снятие с учета) <a class="header-anchor" href="#операция-unregisterperson-снятие-с-учета" aria-label="Permalink to &quot;Операция: `unregisterPerson` (Снятие с учета)&quot;">​</a></h3><p>Соответствие полей для снятия с миграционного учета:</p><table tabindex="0"><thead><tr><th>Поле в API (JSON)</th><th>Таблица БД</th><th>Поле в БД</th><th>Тип в БД</th><th>Обяз.</th><th>Примечание</th></tr></thead><tbody><tr><td><code>personId</code></td><td><code>MIG_UNREG_DATA</code></td><td><code>ID</code></td><td>NUMBER</td><td>✓</td><td>Идентификатор записи</td></tr><tr><td><code>removalReason</code></td><td><code>MIG_UNREG_DATA</code></td><td><code>REMOVALREASON_ID</code></td><td>NUMBER</td><td>✓</td><td>Причина снятия (FK)</td></tr><tr><td><code>departureKpp</code></td><td><code>MIG_UNREG_DATA</code></td><td><code>DEPARTURE_KPP_ID</code></td><td>NUMBER</td><td>✓</td><td>КПП выезда (FK)</td></tr><tr><td><code>departureDate</code></td><td><code>MIG_UNREG_DATA</code></td><td><code>DEPARTURE_DATE</code></td><td>DATE</td><td>✓</td><td>Дата выезда</td></tr><tr><td><code>noticeNumber</code></td><td><code>MIG_UNREG_DATA</code></td><td><code>NOTICENUMBER</code></td><td>VARCHAR2(250)</td><td></td><td>Номер уведомления</td></tr></tbody></table><h2 id="особенности-и-валидация" tabindex="-1">Особенности и валидация <a class="header-anchor" href="#особенности-и-валидация" aria-label="Permalink to &quot;Особенности и валидация&quot;">​</a></h2><ol><li><strong>Оптимистическая блокировка</strong>: Все таблицы ядра и миграции содержат поле <code>VERSION</code> (NUMBER). При вызове API обновления обязательно передается текущий <code>version</code> для предотвращения конфликтов.</li><li><strong>Откат транзакций</strong>: Операция отката (<code>RollbackScenario1</code>) не несет полезной нагрузки в JSON (пустой объект), фактический откат происходит через хранимые процедуры/триггеры БД по <code>caseId</code>.</li><li><strong>Справочники</strong>: При создании лица/документа поля типа <code>DOCUMENTTYPE_ID</code>, <code>CITIZENSHIP_ID</code> в БД ожидают числовые ID, в то время как в API могут передаваться строковые коды (конвертация происходит на уровне <code>Common.Data.Providers</code>).</li></ol>',22)])])}const R=t(r,[["render",a]]);export{E as __pageData,R as default};
